"""Helpers for numeric series."""


def mean(values):
    """Arithmetic mean; raises ValueError on an empty series."""
    if not values:
        raise ValueError("mean of an empty series")
    return sum(values) / len(values)


def gaps(values):
    """Differences between neighbours: gaps([1, 4, 9]) == [3, 5]. Fewer than two values give []."""
    return [values[i + 1] - values[i] for i in range(len(values) - 1)]
